#!/usr/bin/env python3
"""Generate the offline review artifact and Canvas card variants from the installed Manga font assets."""
import argparse,base64
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--out',required=True);args=p.parse_args()
root=Path(__file__).resolve().parents[3];out=Path(args.out);out.mkdir(parents=True,exist_ok=True)
fonts=root/'app/src/main/assets/packs/manga/fonts'
css='\n'.join('@font-face{font-family:'+n+';src:url(data:font/ttf;base64,'+base64.b64encode((fonts/f).read_bytes()).decode()+')}' for n,f in [('body','SchibstedGrotesk.ttf'),('mono','JetBrainsMono.ttf')])
template='<!doctype html><html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Messages · group 1 proposal</title><style>\n\n*{box-sizing:border-box}body{margin:0;background:#e4e4e7;color:#111113;font:16px body,sans-serif}nav{padding:12px;display:flex;gap:8px;flex-wrap:wrap}button,select{font:14px body;padding:8px;background:#fdfdfb;border:1px solid #111113;cursor:pointer}.phone{width:475px;max-width:100vw;height:751px;background:#fdfdfb;display:flex;flex-direction:column;margin:auto;overflow:hidden}.statusbar{padding:20px 28px 12px;display:flex;justify-content:space-between;font-size:14px}.head{height:58px;display:flex;gap:10px;align-items:center;padding:0 8px}.back{font-size:30px}.avatar{border:2px solid #111113;border-radius:50%;background:#111113;color:#fdfdfb;width:38px;height:38px;display:grid;place-items:center;font-weight:700}.name{font-size:18px;font-weight:600}.caption,.delivery{font:700 11px mono,monospace;letter-spacing:1px;color:#6d6d6e;text-transform:uppercase}.messages{flex:1;overflow:auto;padding:12px;display:flex;flex-direction:column;justify-content:end;gap:10px}.bubble{border:2px solid #111113;border-radius:20px;max-width:86%;padding:10px 12px;align-self:start}.out{align-self:end;background:#111113;color:#fdfdfb}.delivery{text-align:right;font-size:10px;min-height:16px}.link{width:282px;padding:0;overflow:hidden}.thumbnail{height:132px;background:#e4e4e7;display:grid;place-items:center;font:700 12px mono;color:#555;letter-spacing:1px}.linktext{padding:10px 12px}.site{font:700 10px mono;text-transform:uppercase;letter-spacing:1px;margin-bottom:5px}.title{font-size:16px;font-weight:600}.out .thumbnail{background:#e4e4e7;color:#555}.typing{font-size:14px;color:#6d6d6e;min-height:24px}.composer{display:flex;align-items:center;gap:8px;margin:8px 8px 24px}.plus{font-size:28px;padding:0 10px}.field{flex:1;border:2px solid #111113;min-height:44px;padding:10px 12px;color:#6d6d6e}.send{float:right;color:#111113}.notice{padding:0 12px 4px;font:11px mono;color:#c8222a}.foot{width:120px;height:4px;border-radius:4px;background:#111113;margin:0 auto 8px}.draft{font-size:13px}.draft .thumbnail{height:66px}.draft .linktext{padding:6px}.explain{max-width:650px;margin:16px auto;padding:0 12px;font-size:14px;line-height:1.5}.selected{background:#111113;color:#fdfdfb}a{color:inherit}</style>\n<nav><strong>Proposed · demo data</strong><button data-mode="status">Send status</button><button data-mode="links">Rich links</button><button data-mode="typing">Typing</button><button data-mode="fallback">Link fallback</button><select id="state" aria-label="Delivery state"><option>Sending…</option><option>Sent</option><option>Delivered</option><option>Read</option><option>Not sent · tap to try again</option></select></nav>\n<main class="phone"><div class="statusbar"><span>8:28</span><span>▮▮▮ Wi-Fi ▰</span></div><header class="head"><span class="back">‹</span><div class="avatar">AD</div><div><div class="name">Ana Demo</div><div class="caption">iMessage · from your Mac</div></div></header><section class="messages" id="messages"></section><div class="notice" id="notice"></div><div class="composer"><span class="plus">+</span><div class="field" id="field">iMessage <span class="send">↑</span></div></div><div class="foot"></div></main><p class="explain" id="explain"></p>\n<script>let initial=\'status\';let mode=initial;const message=document.getElementById(\'messages\'),field=document.getElementById(\'field\'),notice=document.getElementById(\'notice\'),state=document.getElementById(\'state\');function card(out=false,failed=false){return \'<div class="bubble link \'+(out?\'out\':\'\')+\'">\'+(failed?\'\':\'<div class="thumbnail">PREVIEW IMAGE FROM LINK</div>\')+\'<div class="linktext"><div class="site">example.com</div><div class="title">\'+(failed?\'example.com/article\':\'The shared article title\')+\'</div></div></div>\'}function render(){notice.textContent=\'\';field.innerHTML=\'iMessage <span class="send">↑</span>\';state.hidden=mode!==\'status\';if(mode===\'status\'){message.innerHTML=\'<div class="bubble">Are we still on for dinner?</div><div class="bubble out">Yes! 7pm</div><div class="delivery">\'+state.value+\'</div>\';if(state.value.startsWith(\'Not sent\'))notice.textContent=\'Your message stays here. Tap its status to retry.\'}else if(mode===\'typing\'){message.innerHTML=\'<div class="bubble out">See you at seven</div><div class="delivery">Delivered</div><div class="typing">Ana Demo is typing · · ·</div>\'}else{message.innerHTML=card(false,mode===\'fallback\')+card(true,mode===\'fallback\');if(mode===\'links\')field.innerHTML=\'<div class="draft"><div class="thumbnail">PREVIEW IMAGE · × REMOVE</div><div class="linktext">The shared article title · example.com</div></div>https://example.com/article <span class="send">↑</span>\'}document.getElementById(\'explain\').textContent={status:\'Keep the existing bubble and theme. Show Sending immediately; Sent means accepted by the Mac, Delivered/Read require server evidence. Failed sends stay retryable. Status appears once under the latest outgoing run.\',links:\'Same Soma typography, ink and bubble corners. Image/title/site come from metadata; both directions and draft use the same card. Fetching never blocks send. Reserve image space so metadata arrival does not move the reading anchor.\',typing:\'Typing lives above the composer, attributed in a group. It clears on stop, message arrival, timeout or disconnect. Older reading stays anchored. Reference motion tuning follows the restored iOS runtime.\',fallback:\'A link without metadata keeps its host/path and opens normally. No fabricated image, spinner forever, or send delay. Cached metadata works offline.\'}[mode];document.querySelectorAll(\'[data-mode]\').forEach(b=>b.classList.toggle(\'selected\',b.dataset.mode===mode))}document.querySelectorAll(\'[data-mode]\').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;render()});state.onchange=render;render();</script></html>'
html=template.replace('<style>\n\n','<style>'+css+'\n',1)
(out/'messages-parity-group-1.html').write_text(html)
for mode in ['status','links','typing','fallback']:
    card=html.replace("let initial='status'", "let initial='"+mode+"'").replace('</style>','nav,.explain{display:none}.phone{width:100%;height:100vh;max-width:none}.statusbar{padding-top:16px}</style>')
    (out/(mode+'.html')).write_text(card)
